transcricoes_censo.texto:
```sql
SELECT COUNT(DISTINCT CO_ENTIDADE) FROM matriculas;
```

consultas_censo.comando:
SELECT NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO IN (SELECT MIN(NU_ANO_CENSO) FROM matriculas);

SELECT NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO IN (SELECT NU_ANO_CENSO FROM matriculas GROUP BY NU_ANO_CENSO HAVING COUNT(*) = (SELECT COUNT(*) FROM matriculas));

SELECT COUNT(DISTINCT CO_ENTIDADE) AS Número_de_escolas_com_QT_MAT_BAS_igual_a_zero
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS total_escolas_urbanas, COUNT(DISTINCT CO_ENTIDADE) AS total_escolas_rurais
FROM matriculas
WHERE TP_LOCALIZACAO = '2' OR TP_LOCALIZACAO = '3';

SELECT COUNT(DISTINCT CO_ENTIDADE) AS escolas_urbanas, COUNT(DISTINCT CO_ENTIDADE) AS escolas_rurais
FROM matriculas
WHERE TP_LOCALIZACAO = '2';

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN QT_MAT_BAS END) AS total_escolas_urbanas,
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN QT_MAT_BAS END) AS total_escolas_rurais
FROM matriculas;

SELECT AVG(SUM(QT_MAT_BAS)) AS media_urbana
FROM matriculas
WHERE TRIM(SG_UF) <> '' AND TRIM(NO_REGIAO) <> '';

SELECT AVG(SUM(QT_MAT_BAS)) AS media_rural
FROM matriculas
WHERE TRIM(SG_UF) <> '' AND TRIM(NO_REGIAO) = '';
